// 设置 —— 「我的」右上齿轮进来。
//
// 分三组：账号 / 隐私与可见性 / 关于。开关都接真状态（改了立刻生效、
// 返回再进来还在），跳转项通向已有的功能页，剩下少数没有独立屏的给浮层反馈。
// 「对现雇主隐身」关掉时给一次明确警示 —— 这是会让当前公司看到你的唯一开关。

import { useEffect, useState } from 'react';
import 样式 from './我的功能页.module.css';
import { 次级页外壳, 返回栏, 滚动区, 开关 } from '../组件/通用';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { use应用状态 } from '../状态/应用状态';
import 弹层框架 from '../组件/弹层框架';
import { 轻提示 } from '../组件/轻提示';
import { 取后端错误文案 } from '../数据/HTTP客户端';

export default function 设置() {
  const { 返回, 跳转, 替换跳转 } = use导航();
  const { 状态, 派发, 操作, 数据源模式, 后端状态 } = use应用状态();
  const 是后端 = 数据源模式 === 'backend';
  const [提示, 设提示] = useState<string | null>(null);
  const [待关隐身, 设待关隐身] = useState(false);
  const [待退出, 设待退出] = useState(false);

  useEffect(() => {
    if (!提示) return;
    const 定时 = window.setTimeout(() => 设提示(null), 1600);
    return () => window.clearTimeout(定时);
  }, [提示]);

  // P8 Task 4：Backend 账号行只按需读取凭证（设置页零会话请求、零账号范围登记）；
  // Mock 不发任何 P8 调用。非 force 且已成功时操作层零请求。
  useEffect(() => {
    if (!是后端) return;
    void 操作.加载P8凭证().catch(() => undefined);
  }, [是后端, 操作]);

  // P8：唯一 phone_otp 行的服务端 display 原样上屏（无客户端重掩码）；未成功快照
  // （含读取失败）落中性占位，绝不回退硬编码手机号。
  const 手机号显示 = 是后端
    ? 后端状态.credentials.phase === 'success'
      ? 后端状态.credentials.data?.find((行) => 行.provider === 'phone_otp')?.display ?? '未绑定'
      : '—'
    : '138 **** 6021';

  // P3：Mock 下隐私开关照旧走本地归约；Backend 必须等 服务端成功
  // （操作.设置雇主隐私 内部无乐观写），绝不派发本地 切设置开关 假成功。
  // 服务端隐私尚未水合时该开关不可写 —— 其余本地设置不受影响。
  const 隐私已水合 = 数据源模式 === 'mock' || 后端状态.隐私快照 !== null;
  const 切雇主隐私 = async (enabled: boolean) => {
    if (数据源模式 === 'mock') {
      派发({ 型: '切设置开关', 键: '对现雇主隐身' });
      return;
    }
    await 操作.设置雇主隐私(enabled);
  };

  const 开关行 = (键: string) => (
    <div className={样式.行} key={键}>
      <span className={样式.行文字组}>
        <span className={样式.行标题}>{键}</span>
      </span>
      <开关
        开={状态.设置开关[键]}
        标签={键}
        禁用={键 === '对现雇主隐身' ? !隐私已水合 : false}
        切换={() => {
          // 隐身是唯一一个「关掉会让当前公司看到你」的开关，关之前必须确认
          if (键 === '对现雇主隐身' && 状态.设置开关[键]) {
            设待关隐身(true);
            return;
          }
          if (键 === '对现雇主隐身') {
            // Backend 开启写入失败：复用现有轻提示与错误文案映射，不派发本地假成功
            void (async () => {
              try {
                await 切雇主隐私(true);
              } catch (错误) {
                轻提示(取后端错误文案(错误));
              }
            })();
            return;
          }
          派发({ 型: '切设置开关', 键 });
        }}
      />
    </div>
  );

  return (
    <次级页外壳 白底>
      <返回栏 返回={返回} 标题="设置" />

      <滚动区 样式覆盖={{ padding: '14px 18px 24px' }}>
        <div className={样式.组标}>账号</div>
        <div className={样式.平铺组}>
          <div className={样式.行}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>手机号</span>
            </span>
            <span className={样式.行值}>{手机号显示}</span>
          </div>
          {/* Backend 没有实名合同：phone_otp 只证明登录凭据已验证，简历姓名也不是实名，
              不得伪称「已认证」。该行回中性「—」且不可交互；Mock 保留原型演示按钮。 */}
          {是后端 ? (
            <div className={样式.行}>
              <span className={样式.行文字组}>
                <span className={样式.行标题}>实名认证</span>
              </span>
              <span className={样式.行值}>—</span>
            </div>
          ) : (
            <button
              className={`${样式.行} 可点`}
              onClick={() => 设提示('实名认证 · 已通过，无需重复认证')}
            >
              <span className={样式.行文字组}>
                <span className={样式.行标题}>实名认证</span>
              </span>
              <span className={样式.行值}>已认证</span>
              <span className={样式.尖括号}>›</span>
            </button>
          )}
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.账号安全)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>账号与安全</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
        </div>

        <div className={`${样式.组标} ${样式.组标间距}`}>隐私与可见性</div>
        <div className={样式.平铺组}>
          {开关行('对现雇主隐身')}
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.披露偏好)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>披露偏好</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.屏蔽名单)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>屏蔽名单</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.接触记录)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>谁接触过我</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
        </div>



        <div className={`${样式.组标} ${样式.组标间距}`}>关于</div>
        <div className={样式.平铺组}>
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.帮助与客服)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>帮助与客服</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.反馈)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>反馈与举报</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
          <button className={`${样式.行} 可点`} onClick={() => 跳转(路径.用户协议)}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>用户协议与隐私政策</span>
            </span>
            <span className={样式.尖括号}>›</span>
          </button>
          <div className={样式.行}>
            <span className={样式.行文字组}>
              <span className={样式.行标题}>当前版本</span>
            </span>
            <span className={样式.行值}>0.9.0（原型）</span>
          </div>
        </div>

        <button className={`${样式.危险键} 可点`} onClick={() => 设待退出(true)}>
          退出登录
        </button>

        <div className={样式.版本}>
          工作蜂 A2A 招聘原型 · 前端 0.9.0
          <br />
          人力资源服务许可证 · 算法举报 · 资质证照
        </div>
      </滚动区>

      {待关隐身 ? (
        <弹层框架 标签="关闭对现雇主隐身" 遮罩类名={样式.遮罩} 面板类名={样式.确认框} 位置="居中" 关闭={() => 设待关隐身(false)}>
            <div className={样式.确认标题}>关闭「对现雇主隐身」？</div>
            <div className={样式.确认正文}>
              关闭后，你当前公司及其关联公司可以在平台上看到你的匿名画像，也可能主动发起接触。
              保密求职期间建议保持开启。
            </div>
            <div className={样式.确认键行}>
              <button className={`${样式.确认取消} 可点`} onClick={() => 设待关隐身(false)}>
                保持开启
              </button>
              <button
                className={`${样式.确认执行} 可点`}
                onClick={async () => {
                  try {
                    // 服务端生效才收口：Mock 是同步归约，Backend 等 操作.设置雇主隐私 兑现
                    await 切雇主隐私(false);
                    设待关隐身(false);
                    设提示('隐身已关闭');
                  } catch (错误) {
                    // 写入失败：保留弹层可重试或取消（与退出登录同口径，不改弹层 DOM/CSS）；
                    // 复用现有轻提示与错误文案映射，失败不再静默
                    轻提示(取后端错误文案(错误));
                  }
                }}
              >
                仍要关闭
              </button>
            </div>
        </弹层框架>
      ) : null}

      {待退出 ? (
        <弹层框架 标签="退出当前账号" 遮罩类名={样式.遮罩} 面板类名={样式.确认框} 位置="居中" 关闭={() => 设待退出(false)}>
            <div className={样式.确认标题}>退出当前账号？</div>
            <div className={样式.确认正文}>
              退出后代理仍会按既有规则继续匹配和初筛，但你收不到需要确认的提醒。
            </div>
            <div className={样式.确认键行}>
              <button className={`${样式.确认取消} 可点`} onClick={() => 设待退出(false)}>
                取消
              </button>
              <button
                className={`${样式.确认执行} 可点`}
                /* 可访问名称必须与上面那枚触发键（同样写着「退出登录」）区分开。
                   弹层框架用的是 <dialog open>（组件/弹层框架.tsx:62-64），那是**非模态**的：
                   页面其余部分既不 inert 也不从可访问树里剪枝，所以确认层开着的时候，
                   读屏用户按钮浏览会连着读到两枚一模一样的「退出登录」，分不出哪个是确认。
                   做法与本仓库既有的同类修复一致（我的简历的删除确认叫「删除附件简历」）：
                   只改可访问名称、不动可见文案，视觉基线一个像素都不动。

                   名字还必须避开遮罩键：弹层框架给遮罩生成的是 `关闭${标签}`
                   （组件/弹层框架.tsx:61），本层标签就是「退出当前账号」，所以遮罩叫
                   「关闭退出当前账号」。确认键若直接叫「退出当前账号」，就成了遮罩名的子串 ——
                   Playwright 的 getByRole({name}) 与 agent-browser 不带 --exact 的 --name
                   都是子串匹配，会同时命中两枚。前缀「确认」把它从子串关系里摘出来。 */
                aria-label="确认退出当前账号"
                onClick={async () => {
                  try {
                    await 操作.退出登录();
                    替换跳转(路径.登录);
                  } catch {
                    // 退出失败：保留弹层，用户可重试或取消（不改弹层 DOM/CSS）
                    设待退出(false);
                  }
                }}
              >
                退出登录
              </button>
            </div>
        </弹层框架>
      ) : null}

      {提示 ? <div className={样式.浮层提示}>{提示}</div> : null}
    </次级页外壳>
  );
}
